/**
 * The 0-0 cue document format, version 1.
 *
 * A cue document describes everything that happens around a piece of media:
 * where things can appear (regions) and what appears when (cues). It is plain
 * JSON so it can be written by hand, generated by tools, or converted from
 * WebVTT. See docs/cue-format.md for the full specification.
 */

export const CUE_FORMAT_VERSION = 1;

/** Where a region is placed relative to the media. */
export type RegionPlacement = 'sidebar' | 'below' | 'overlay';

/** Anchor for overlay regions. Ignored for other placements. */
export type OverlayPosition =
  | 'top-left'
  | 'top-right'
  | 'bottom-left'
  | 'bottom-right'
  | 'center';

export interface Region {
  /** Unique identifier referenced by cues. */
  id: string;
  placement: RegionPlacement;
  /** Accessible name for the region, e.g. "Transcript". */
  label?: string;
  /** Overlay anchor; defaults to "top-right". */
  position?: OverlayPosition;
  /**
   * When true, content entering this region is announced politely to
   * assistive technology. Leave off for busy regions such as transcripts.
   */
  announce?: boolean;
}

export interface CueDocumentMetadata {
  title?: string;
  description?: string;
  /** BCP 47 language tag, e.g. "en" or "pt-BR". */
  language?: string;
  /** Media duration in seconds, if known. */
  duration?: number;
  [key: string]: unknown;
}

export interface Cue<TData = unknown> {
  /** Unique within the document. */
  id: string;
  /** Start time in seconds, inclusive. */
  start: number;
  /** End time in seconds, exclusive. Must be greater than start. */
  end: number;
  /** Element type, e.g. "transcript", "image", "link", "chapter". */
  type: string;
  /** Id of the region the cue renders into. */
  region: string;
  /** Type-specific payload. */
  data: TData;
}

export interface CueDocument {
  version: typeof CUE_FORMAT_VERSION;
  metadata?: CueDocumentMetadata;
  regions: Region[];
  cues: Cue[];
}

/** Payloads for the built-in element types. */
export interface TranscriptData {
  text: string;
  speaker?: string;
}

export interface ImageData {
  src: string;
  /** Required. Use an empty string only for purely decorative images. */
  alt: string;
  caption?: string;
  credit?: string;
  width?: number;
  height?: number;
}

export interface LinkData {
  title: string;
  url: string;
  /** Publication or site name shown on the card. */
  source?: string;
  summary?: string;
}

export interface ChapterData {
  title: string;
}
